INSERT INTO editorial_documents (document_type, locale, schema_version, document, status, owner_artist_id, revision)
SELECT 'artist_biography', 'en', 1, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Andre Veloz —born Andreina Martínez Hiraldo in St. Croix, U.S. Virgin Islands, in the 1980s, and nicknamed “La Fosforera”— is a Dominican singer, songwriter, painter and actress raised in Santiago de los Caballeros and based in New York, one of the few women singing traditional bachata."}]},{"type":"paragraph","content":[{"type":"text","text":"Roots","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"She was born in Christiansted, where her grandmother ran a business, and was brought to the Dominican Republic as a baby. From about the age of eight she lived in Santiago, with spells in Imbert and Las Canas, and at twenty-one she moved to the United States, where she worked and studied while singing in restaurants, clubs and Latin celebrations around New York."}]},{"type":"paragraph","content":[{"type":"text","text":"Before bachata","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Bachata was not where she started. According to her label’s biography, at fourteen she was already playing rock and jazz with a band, «Los Horizontes Verticales», and it lists Santiago musicians she worked with, among them "},{"type":"artistReference","attrs":{"occurrenceId":"de72dce3-c3ee-476e-b12e-6b646a9ef643","artistId":"8e29188a-215b-4c6c-b34a-45b381765e46","displayText":"Xiomara Fortuna"}},{"type":"text","text":", "},{"type":"artistReference","attrs":{"occurrenceId":"3c34ccf0-0e42-4c97-8b50-bc1dd07750b4","artistId":"58fef0f7-b2a4-42bb-ac8c-462dd66609e4","displayText":"Sandy Gabriel"}},{"type":"text","text":", Patricia Pereyra, Fellé Vega and Rafael Mirabal. She has called bachata “the blues of us Dominicans”, with the same feeling and the same bitterness."}]},{"type":"paragraph","content":[{"type":"text","text":"«Si la ves» and a first album","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"«IASO Records» signed her in 2013 after hearing her sing «Si la ves», and her first album, «Andre Veloz», followed in 2014, warmly received by Dominicans in the United States. In May 2015 NY1 featured her as one of the few women performing traditional bachata."}]},{"type":"paragraph","content":[{"type":"text","text":"«Eta’ que ta’ aquí» and the Soberano nomination","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Her 2018 single «Eta’ que ta’ aquí» went viral in the United States and the Dominican Republic; on 12 March 2018 El Nacional wrote that it was being repeated in streets, homes and offices despite its simple lyrics. She made a remix with "},{"type":"artistReference","attrs":{"occurrenceId":"d142b3c7-2727-4eaa-b2f4-a2f3038b428c","artistId":"6321da6c-e2d5-490a-a4e8-416bbee81edf","displayText":"Don Miguelo"}},{"type":"text","text":" and in December 2018 released «La Pendeja», about a romantic disappointment. In the 2019 Premios Soberano she was nominated for Revelación del Año, together with «Lo Blanquito», El Deivy Jiménez, "},{"type":"artistReference","attrs":{"occurrenceId":"5afc58e9-5f88-4f39-b97c-f63ad16f7747","artistId":"71ebd02b-8ba4-4cd7-b7e4-a990a9c3c3bb","displayText":"Rochy RD"}},{"type":"text","text":" and Lírico en la Casa; «Lo Blanquito» took the award."}]},{"type":"paragraph","content":[{"type":"text","text":"Legacy","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"She continues to release music, including «Juguito de Odio» in September 2025 and another release in May 2026, and has been announced for a free festival in Greensboro. The newspaper El Diario reported that she guided the Travel Channel host Andrew Zimmern through the food scene of the Bronx."}]}]}'::jsonb, 'published', id, 1 FROM artists WHERE slug = 'andre-veloz'
