INSERT INTO editorial_entity_references (editorial_document_id, occurrence_id, entity_type, target_artist_id)
  SELECT d.id, '162eb6ea-2d82-4189-8092-d9a95937844f', 'artist', 'da791d26-8bab-45e4-b7d1-f09314869f09' FROM editorial_documents d JOIN artists x ON x.id = d.owner_artist_id
