  SELECT d.id, '98774494-4b5b-4381-8a03-b2855bd9c8eb', 'artist', 'da791d26-8bab-45e4-b7d1-f09314869f09' FROM editorial_documents d JOIN artists x ON x.id = d.owner_artist_id
